import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
def nmse(p,f): 
    r=f(p); return np.mean((r-y)**2)/np.var(y)
models={
 'a*A^n*t^m - b*A^k': (lambda p: p[0]*A**p[1]*t**p[2]-p[3]*A**p[4], [1,2,0.5,1,1]),
 'a*A^n - b*A^k*(1+c t)': (lambda p: p[0]*A**p[1]-p[2]*A**p[3]*(1+p[4]*t), [1,2,1,1,0.1]),
 'A*(a*A^n*(1+b t) - c*A^k*(1+d t)) ': (lambda p: A*(p[0]*A**p[1]*(1+p[2]*t)-p[3]*A**p[4]*(1+p[5]*t)), [1,1,0.1,1,1,0.1]),
 'a*A^n*exp(b t)-c*A^k*exp(d t)': (lambda p: p[0]*A**p[1]*np.exp(p[2]*t)-p[3]*A**p[4]*np.exp(p[5]*t), [1,2,0.1,1,1,0.1]),
}
for name,(f,p0) in models.items():
    best=None
    for s in range(30):
        p=np.array(p0)*np.exp(np.random.randn(len(p0))*0.5)*(1 if s else 1)
