import numpy as np, itertools
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
ns=np.arange(0,3.01,0.25)
tb={'1':np.ones_like(t),'t':t,'1/t':1/t,'sqrt t':np.sqrt(t),'exp(-t)':np.exp(-t),'log t':np.log(t),'t^2':t**2}
res=[]
for n,m in itertools.combinations(ns,2):
    for tn1,tn2 in [('1','t'),('1','1/t'),('1','sqrt t'),('1','exp(-t)'),('1','log t'),('1','t^2')]:
        X=np.column_stack([A**n, A**n*tb[tn2], A**m, A**m*tb[tn2]])
        c,*_=np.linalg.lstsq(X,y,rcond=None)
        r=np.mean((X@c-y)**2)/np.var(y)
        res.append((r,n,m,tn2))
res.sort()
for r in res[:8]: print(r)
